const fs = require('fs');
const dir = '/vault/60-投资/记账';
const inbox = '/vault/99-Diary/n8n-提醒.md';
const now = new Date();
const y = now.getFullYear();
const m = String(now.getMonth() + 1).padStart(2, '0');
const d = String(now.getDate()).padStart(2, '0');
const tasks = [];

if (now.getDate() === 1) {
  const f = `${dir}/${y}${m}.md`;
  if (!fs.existsSync(f)) {
    const lastDay = new Date(y, now.getMonth() + 1, 0).getDate();
    tasks.push(`- [ ] 建 ${y}${m} 记账笔记（复制 00-Template/记账-月度模板） 📅 ${y}-${m}-${lastDay}`);
  }
}

if (now.getDate() === 15) {
  const prev = new Date(y, now.getMonth() - 1, 1);
  const py = prev.getFullYear();
  const pm = String(prev.getMonth() + 1).padStart(2, '0');
  const lastDay = new Date(y, now.getMonth(), 0).getDate();
  tasks.push(`- [ ] 核对 ${py}${pm} 记账：总览余额与入账补齐、对照大额贷款台账 📅 ${y}-${m}-${lastDay}`);
}

if (tasks.length > 0) {
  fs.appendFileSync(inbox, `\n## ${y}-${m}-${d} 记账月历\n\n${tasks.join('\n')}\n`);
}

return [{ json: { wrote: tasks.length, tasks } }];
